import React from 'react';

interface IconProps {
  color?:
    | 'primary'
    | 'secondary'
    | 'activated'
    | 'selected'
    | 'currentColor'
    | string;
  width?: number;
  height?: number;
  viewBox?: string;
  path?: React.ReactNode;
  className?: string;
  size?: 'sm' | 'md';
}

const colorMap: Record<string, string> = {
  primary: '#437B9A',
  secondary: '#112F40',
  activated: '#F6D4C2',
  selected: '#E5E5E5',
};

export const Icon = ({
  color = 'currentColor',
  width,
  height,
  viewBox,
  path,
  className,
  size = 'md',
}: IconProps) => {
  const fillColor = color ? colorMap[color] || color : 'currentColor';

  // Definir tamaños basados en la prop size
  const sizeMap = {
    sm: { width: 16, height: 16, viewBox: '0 0 16 16' },
    md: { width: 24, height: 24, viewBox: '0 0 24 24' },
  };

  const finalSize = sizeMap[size];
  const finalWidth = width ?? finalSize.width;
  const finalHeight = height ?? finalSize.height;
  const finalViewBox = viewBox ?? finalSize.viewBox;

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={finalWidth}
      height={finalHeight}
      viewBox={finalViewBox}
      fill="none"
      className={`shrink-0 ${className}`}
      style={{
        display: 'block',
        maxWidth: '100%',
        height: 'auto',
        color: fillColor,
      }}
    >
      {path}
    </svg>
  );
};

